{
  "query": "SELECT campaign.name, campaign.status, metrics.cost_micros, metrics.clicks, metrics.impressions, metrics.ctr, metrics.average_cpc, metrics.conversions, metrics.conversions_value, metrics.cost_per_conversion FROM campaign WHERE segments.date DURING YESTERDAY ORDER BY metrics.cost_micros DESC"
}

parameters.jsCode:
const rows = $input.first().json[0]?.results || [];

let totalGasto = 0;
let totalClicks = 0;
let totalImpresiones = 0;
let totalConversiones = 0;
let totalValorConv = 0;

const campanas = [];

for (const row of rows) {
  const m = row.metrics;
  const gasto = (m.costMicros || 0) / 1_000_000;
  const clicks = m.clicks || 0;
  const imp = m.impressions || 0;
  const conv = m.conversions || 0;
  const valConv = m.conversionsValue || 0;
  const ctr = ((m.ctr || 0) * 100).toFixed(2);
  const cpc = ((m.averageCpc || 0) / 1_000_000).toFixed(2);
  const cpa = conv > 0 ? (gasto / conv).toFixed(2) : 'N/A';
  const roas = gasto > 0 ? (valConv / gasto).toFixed(2) : '0';

  totalGasto += gasto;
  totalClicks += clicks;
  totalImpresiones += imp;
  totalConversiones += conv;
  totalValorConv += valConv;

  const estado = row.campaign.status === 'ENABLED' ? '🟢' : '⏸️';

  campanas.push(`
    <tr>
      <td>${estado} ${row.campaign.name}</td>
      <td>$${gasto.toFixed(0)}</td>
      <td>${imp.toLocaleString()}</td>
      <td>${clicks}</td>
      <td>${ctr}%</td>
      <td>$${cpc}</td>
      <td>${conv}</td>
      <td>${roas}x</td>
      <td>${cpa === 'N/A' ? '-' : '$' + cpa}</td>
    </tr>`);
}

const roasTotal = totalGasto > 0 ? (totalValorConv / totalGasto).toFixed(2) : '0';
const ctrTotal = totalImpresiones > 0 ? ((totalClicks / totalImpresiones) * 100).toFixed(2) : '0';

const hoy = new Date().toLocaleDateString('es-AR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const html = `
<h1>📊 Reporte YaniTrend - Google Ads</h1>
<p><b>Fecha:</b> ${hoy}</p>

<h2>Resumen General (Ayer)</h2>
<table border="1" cellpadding="8" style="border-collapse:collapse;font-family:Arial">
  <tr style="background:#f0f0f0">
    <td><b>Gasto total</b></td>
    <td><b>Impresiones</b></td>
    <td><b>Clicks</b></td>
    <td><b>CTR</b></td>
    <td><b>Conversiones</b></td>
    <td><b>ROAS</b></td>
  </tr>
  <tr>
    <td>$${totalGasto.toFixed(0)} ARS</td>
    <td>${totalImpresiones.toLocaleString()}</td>
    <td>${totalClicks}</td>
    <td>${ctrTotal}%</td>
    <td>${totalConversiones}</td>
    <td>${roasTotal}x</td>
  </tr>
</table>

<h2>Por Campaña</h2>
<table border="1" cellpadding="8" style="border-collapse:collapse;font-family:Arial">
  <tr style="background:#4285f4;color:white">
    <th>Campaña</th>
    <th>Gasto</th>
    <th>Impres.</th>
    <th>Clicks</th>
    <th>CTR</th>
    <th>CPC</th>
    <th>Conv.</th>
    <th>ROAS</th>
    <th>CPA</th>
  </tr>
  ${campanas.join('')}
</table>

<br/>
<p style="color:#666">📧 Reporte automático de YaniTrend | <a href="https://ads.google.com/">Abrir Google Ads</a></p>
`;

return [{ json: { html, totalGasto: totalGasto.toFixed(0), totalConversiones, roasTotal, campanas: rows.length } }];
